'use strict';
const data=window.TINY_DATA, $=id=>document.getElementById(id);
const extras={mint:['길을 잘 알고 싶었는데, 자꾸 다른 것이 눈에 들어와요. 접힌 지도 한쪽에서 시작된 하루.','가볍게 걷는 호기심'],cheese:['좋은 선물을 주고 싶었어요. 그런데 햇빛은 뚜껑을 닫으면 어디로 가는 걸까요?','햇볕 아래 느긋한 장난'],popo:['처음 듣는 소리와 익숙한 집 사이. 포포는 오늘의 여름을 어디에 두고 싶을까요?','맑은 소리와 포근한 여백'],lumi:['조용한 관객 앞에서 루미의 말이 빨라져요. 혹시 놓치고 있던 반응이 있을까요?','숲속 무대의 경쾌함'],nunu:['방금까지 있던 발자국이 사라져요. 누누는 자기가 머문 곳을 어떻게 알릴까요?','조용한 틈의 작은 장난'],piko:['피코는 신이 나서 벌써 다음 모퉁이예요. 친구는 그 길에서 무엇을 보고 있었을까요?','물방울처럼 통통 튀는 리듬']};
let selected='mint',opener=null;
data.characters.forEach((c,i)=>{const b=document.createElement('button');b.id='tab-'+c.id;b.type='button';b.setAttribute('role','tab');b.setAttribute('aria-controls','friend-panel');b.setAttribute('aria-selected','false');b.tabIndex=-1;const im=document.createElement('img');im.src=`assets/${c.id}.png`;im.alt='';im.className='pixel';b.append(im,document.createTextNode(c.name));b.onclick=()=>choose(c.id);b.onkeydown=e=>{let next;if(e.key==='ArrowRight')next=(i+1)%6;if(e.key==='ArrowLeft')next=(i+5)%6;if(e.key==='Home')next=0;if(e.key==='End')next=5;if(next!==undefined){e.preventDefault();choose(data.characters[next].id);$('tab-'+data.characters[next].id).focus();}};$('friend-tabs').append(b);});
function choose(id){selected=id;const c=data.characters.find(x=>x.id===id);data.characters.forEach(x=>{const b=$('tab-'+x.id);b.setAttribute('aria-selected',String(x.id===id));b.tabIndex=x.id===id?0:-1;});$('friend-panel').setAttribute('aria-labelledby','tab-'+id);$('home-image').src=`assets/${id}-home.png`;$('home-image').alt=c.home+'의 풍경';$('home-label').textContent=c.home;$('friend-sprite').src=`assets/${id}.png`;$('friend-sprite').alt=c.name;$('friend-species').textContent=c.species+' · '+c.home;$('friend-name').textContent=c.name;$('friend-description').textContent=c.personality;const story=data.stories.find(s=>s.characterId===id&&s.kind==='episode');$('story-title').textContent=story.title;$('story-tease').textContent=extras[id][0];$('music-note').textContent='음악 준비 중 · '+extras[id][1];}
function read(kind){const s=data.stories.find(x=>x.characterId===selected&&x.kind===kind);if(!s)return;opener=document.activeElement;$('reader-friend').textContent=data.characters.find(c=>c.id===selected).name+'의 이야기';$('reader-title').textContent=s.title;$('reader-text').replaceChildren();let lastTitle='';s.pages.forEach(page=>{if(page.title!==lastTitle){const h=document.createElement('h3');h.textContent=page.title;$('reader-text').append(h);lastTitle=page.title;}page.blocks.forEach(block=>{const p=document.createElement('p');if(block.speaker){p.className='speech';const b=document.createElement('b');b.textContent=block.speaker;p.append(b);}p.append(document.createTextNode(block.text));$('reader-text').append(p);});});$('reader').showModal();$('reader').scrollTop=0;document.body.classList.add('reading');$('close-reader').focus();}
$('read-first').onclick=()=>read('episode');$('read-intro').onclick=()=>read('background');$('close-reader').onclick=()=>$('reader').close();$('reader-done').onclick=()=>$('reader').close();$('reader').addEventListener('close',()=>{document.body.classList.remove('reading');opener?.focus();});$('reader').addEventListener('click',e=>{if(e.target===$('reader')){const r=$('reader').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('reader').close();}});choose(selected);
